import React, { useState, useEffect } from 'react';
import axios from 'axios';

const Dashboard = () => {
  const [threatData, setThreatData] = useState(null);
  const [alerts, setAlerts] = useState([]);
  const [loading, setLoading] = useState(true);

  const [iotDevices, setIotDevices] = useState([
    { id: "IOT-RX-01", name: "Riyadh Hub", status: "Online", risk: "Low", firmware: "v2.1" },
    { id: "IOT-DXB-02", name: "Dubai Gateway", status: "Online", risk: "Low", firmware: "v2.0" },
    { id: "IOT-NEOM-03", name: "NEOM Sensor", status: "Online", risk: "Low", firmware: "v1.8" }
  ]);

  const discoverNewDevice = () => {
    const regions = ["Riyadh", "Dubai", "Abu Dhabi", "NEOM", "Jeddah"];
    const types = ["Camera", "Power Grid", "Water Sensor", "Smart Light", "Traffic Monitor"];
    const newDevice = {
      id: `IOT-${Math.floor(Math.random() * 9000 + 1000)}`,
      name: `${regions[Math.floor(Math.random() * regions.length)]} ${types[Math.floor(Math.random() * types.length)]}`,
      status: "Online",
      risk: Math.random() > 0.8 ? "Medium" : "Low",
      firmware: "v1." + Math.floor(Math.random() * 9)
    };
    setIotDevices(prev => [newDevice, ...prev].slice(0, 10));
  };

  const fetchThreats = async () => {
    try {
      let testPayload = "normal_traffic";
      let testIp = `192.168.1.${Math.floor(Math.random() * 255)}`;
      let testRequests = Math.floor(Math.random() * 300); 
      let testSize = Math.floor(Math.random() * 2000);

      const randomVal = Math.random();

      if (randomVal > 0.8) {
        testPayload = "UNION SELECT * FROM users--";
        testIp = "HACKER_SQL_INJECT"; 
      } else if (randomVal > 0.6) {
        testRequests = 900; 
        testSize = 150;
        testIp = "10.0.0." + Math.floor(Math.random() * 100); // Brute force IP
      }

      const res = await axios.post('http://localhost:8000/analyze-traffic', {
        ip_source: testIp,
        packet_size: testSize,
        request_count: testRequests,
        payload: testPayload
      });

      setThreatData(res.data);
      setLoading(false);

      if (res.data.is_anomaly) {
        // Backend se aane wala ip_source aur location dono store kar rahe hain
        setAlerts(prev => [{ 
          id: Date.now(), 
          ...res.data, 
          ip_source: testIp, // Tracking the source IP
          time: new Date().toLocaleTimeString() 
        }, ...prev].slice(0, 6));
      }
    } catch (err) {
      console.error("ML Engine Connection Error", err);
    }
  };

  useEffect(() => {
    const discoveryTimer = setInterval(discoverNewDevice, 10000);
    const threatTimer = setInterval(fetchThreats, 5000);
    return () => {
      clearInterval(discoveryTimer);
      clearInterval(threatTimer);
    };
  }, []);

  return (
    <div style={{ backgroundColor: '#010409', color: '#c9d1d9', minHeight: '100vh', padding: '25px', fontFamily: 'Arial, sans-serif' }}>

      <div style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '1px solid #30363d', paddingBottom: '15px' }}>
        <h2 style={{ color: '#58a6ff', margin: 0 }}>🛡️ CyberGuard AI | Vision 2030 SOC Monitor</h2>
        <div style={{ textAlign: 'right', fontSize: '12px' }}>
          <span style={{ color: '#3fb950' }}>● AI ENGINE ACTIVE</span> | UAE-KSA REGION
        </div>
      </div>

      {/* IoT Assets Section */}
      <h3 style={{ marginTop: '25px', fontSize: '18px', color: '#8b949e' }}>🌐 IoT Infrastructure Assets (Live Discovery)</h3>
      <div style={{ display: 'flex', overflowX: 'auto', gap: '15px', padding: '10px 0' }}>
        {iotDevices.map(device => (
          <div key={device.id} style={{ minWidth: '200px', background: '#0d1117', border: '1px solid #30363d', padding: '15px', borderRadius: '8px', borderLeft: `5px solid ${device.risk === 'Low' ? '#3fb950' : '#f85149'}` }}>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <strong>{device.name}</strong>
              <span style={{ fontSize: '10px', color: '#8b949e' }}>{device.id}</span>
            </div>
            <p style={{ margin: '10px 0 5px 0', fontSize: '13px' }}>Status: {device.status}</p>
            <p style={{ margin: 0, fontSize: '11px', color: '#8b949e' }}>Risk: {device.risk} | FW: {device.firmware}</p>
          </div>
        ))}
      </div>

      {/* AI Cards */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px', marginTop: '30px' }}>
        <div style={{ background: '#161b22', border: '1px solid #30363d', padding: '20px', borderRadius: '10px' }}>
          <h4 style={{ margin: '0 0 10px 0' }}>Traffic Analysis Node</h4>
          {loading ? <p>Scanning Network...</p> : (
            <p style={{ fontSize: '18px', color: threatData.is_anomaly ? '#f85149' : '#3fb950' }}>
              {threatData.is_anomaly ? '⚠️ ANOMALY AT ' : '✅ SECURE: '} {threatData.location.toUpperCase()}
            </p>
          )}
        </div>
        <div style={{ background: '#161b22', border: '1px solid #30363d', padding: '20px', borderRadius: '10px' }}>
          <h4 style={{ margin: '0 0 10px 0' }}>Defense Response</h4>
          <p style={{ fontSize: '14px' }}>Recommendation: <strong>{threatData?.recommendation || 'Monitoring...'}</strong></p>
          <button style={{ background: '#238636', color: 'white', border: 'none', padding: '8px 15px', borderRadius: '4px', marginTop: '5px', cursor: 'pointer' }}>Deploy Security Patch</button>
        </div>
      </div>

      {/* THREAT LOGS TABLE (With Origin Column) */}
      <div style={{ marginTop: '30px', background: '#0d1117', border: '1px solid #30363d', borderRadius: '10px', overflow: 'hidden' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead style={{ background: '#161b22', textAlign: 'left', color: '#8b949e' }}>
            <tr>
              <th style={{ padding: '12px' }}>Time</th>
              <th style={{ padding: '12px' }}>Incident (EN)</th>
              <th style={{ padding: '12px' }}>Severity</th>
              <th style={{ padding: '12px' }}>Origin (IP/Loc)</th> {/* Naya Header */}
              <th style={{ padding: '12px' }}>Arabic Insight (JAIS)</th>
            </tr>
          </thead>
          <tbody>
            {alerts.map(alert => (
              <tr key={alert.id} style={{ borderBottom: '1px solid #21262d' }}>
                <td style={{ padding: '12px', fontSize: '12px' }}>{alert.time}</td>
                <td style={{ padding: '12px' }}>{alert.analysis_report}</td>
                <td style={{ padding: '12px' }}>
                  <span style={{ background: alert.threat_level === 'Critical' ? '#490000' : '#3b2300', color: alert.threat_level === 'Critical' ? '#ffa1a1' : '#ffab70', padding: '2px 8px', borderRadius: '10px', fontSize: '11px' }}>
                    {alert.threat_level}
                  </span>
                </td>
                {/* Yahan Attacker ki IP aur Location dikhayenge */}
                <td style={{ padding: '12px', fontSize: '12px', color: '#58a6ff' }}>
                  {alert.ip_source} <br/> 
                  <small style={{ color: '#8b949e' }}>Target: {alert.location}</small>
                </td>
                <td style={{ padding: '12px', direction: 'rtl', textAlign: 'right', color: '#8b949e', fontSize: '13px', fontFamily: 'Arial' }}>
                  {alert.arabic_report}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {alerts.length === 0 && <p style={{ padding: '20px', textAlign: 'center', color: '#8b949e' }}>Listening for network anomalies...</p>}
      </div>
    </div>
  );
};

export default Dashboard;
